// AOT block runtime: shared types and inline helpers.
//
// Hand-written.  The block bodies and the block table live in
// emu/aot_blocks.c, which is machine generated by tools/aot.py.
//
// Design (docs/PLAN_AOT.md 3):
//   * one C function per basic block, one call per block
//   * dispatch is a two level table: page = (lpc >> 8) & 0x3fff, then
//     slot = lpc & 0xff
//   * a block never runs an uncovered instruction itself: it stores the
//     register file back and calls AotCtx::fallback(), which executes
//     exactly one instruction with the interpreter, then returns to the
//     dispatcher
//   * interrupts are checked after every instruction, exactly where the
//     interpreter checks them, so the instruction stream stays identical
#ifndef EMU_AOT_H
#define EMU_AOT_H

#include <stdint.h>

// Status register bits (unsp.h: UNSP_N/Z/S/C).
#define AOT_N 0x0200u
#define AOT_Z 0x0100u
#define AOT_S 0x0080u
#define AOT_C 0x0040u

struct AotCtx;

typedef void (*AotFn)(struct AotCtx *c);

typedef struct AotPage
{
	AotFn fn[0x100];
	uint8_t cnt[0x100];   // native instructions in that block
	uint16_t cyc[0x100];  // worst-case cycles of that block
} AotPage;

typedef struct AotCtx
{
	// Points straight at m_core->m_r so a block mutates the live register
	// file: no 16-word copy on every block entry and exit.
	uint32_t *r;        // guest r0..r7 (r6 = SR, r7 = PC low half)
	uint32_t sb;        // shift buffer, only the low 4 bits are used
	int32_t icount;     // copied back to m_core->m_icount when a block returns
	uint16_t *ram;      // flat RAM window handed over by the SoC
	uint32_t ram_limit; // highest address served by the flat window (inclusive)
	void *dev;          // unsp_device*

	// Slow paths.  Never touched by a block that stays inside the window.
	uint16_t (*bus_rd)(void *dev, uint32_t address);
	void (*bus_wr)(void *dev, uint32_t address, uint16_t value);
	void (*fallback)(void *dev, AotCtx *c, uint32_t lpc);

	const uint32_t *sirq; // &m_core->m_sirq

	// Tracing hooks (may be null; the dispatch loop mirrors them).
	void (*insn_hook)(void *opaque, uint32_t lpc);
	void *insn_opaque;
	void (*cycle_hook)(void *opaque, uint32_t lpc, int cycles);
	void *cycle_opaque;
	uint32_t *blk_hist;
} AotCtx;

static inline uint32_t aot_lpc(const AotCtx *c)
{
	return ((c->r[6] & 0x3fu) << 16) | (c->r[7] & 0xffffu);
}

// Same maths as unsp_device::add_lpc()/set_pc_lpc(): the top six PC bits live
// in SR[0..5], so a jump target must never be written into r7 alone.
static inline void aot_set_pc(AotCtx *c, uint32_t lpc)
{
	c->r[6] = (c->r[6] & 0xffc0u) | ((lpc >> 16) & 0x3fu);
	c->r[7] = lpc & 0xffffu;
}

// Counters for where the block body's memory traffic actually lands.  The
// fast path (guest RAM below ram_limit) is two instructions; everything else
// is an indirect call into aot_bus_rd/wr and then a virtual call into
// Gpce4::read16/write16.  Keeping the four counters apart says whether the
// 760 cycles/dispatch measured on device are dominated by that call chain.
// Compiled out unless C3_AOTACC is set: the += would otherwise sit in the
// hottest loop in the firmware.
#ifndef C3_AOTACC
#define C3_AOTACC 0
#endif

#if C3_AOTACC
extern uint32_t g_rd_fast, g_rd_slow, g_wr_fast, g_wr_slow;
#define AOT_ACC_RD_FAST() (++g_rd_fast)
#define AOT_ACC_RD_SLOW() (++g_rd_slow)
#define AOT_ACC_WR_FAST() (++g_wr_fast)
#define AOT_ACC_WR_SLOW() (++g_wr_slow)
#else
#define AOT_ACC_RD_FAST() ((void)0)
#define AOT_ACC_RD_SLOW() ((void)0)
#define AOT_ACC_WR_FAST() ((void)0)
#define AOT_ACC_WR_SLOW() ((void)0)
#endif

static inline uint16_t aot_rd(AotCtx *c, uint32_t address)
{
	if (address <= c->ram_limit)
	{
		AOT_ACC_RD_FAST();
		return c->ram[address];
	}
	AOT_ACC_RD_SLOW();
	return c->bus_rd(c->dev, address);
}

static inline void aot_wr(AotCtx *c, uint32_t address, uint16_t value)
{
	if (address <= c->ram_limit)
	{
		AOT_ACC_WR_FAST();
		c->ram[address] = value;
		return;
	}
	AOT_ACC_WR_SLOW();
	c->bus_wr(c->dev, address, value);
}

// unsp_device::update_nz()
static inline void aot_nz(AotCtx *c, uint32_t value)
{
	uint32_t sr = c->r[6] & ~(AOT_N | AOT_Z);
	if (value & 0x8000u)
		sr |= AOT_N;
	if ((uint16_t)value == 0)
		sr |= AOT_Z;
	c->r[6] = sr;
}

// unsp_device::update_nzsc()
static inline void aot_nzsc(AotCtx *c, uint32_t value, uint32_t r0, uint32_t r1)
{
	uint32_t sr = c->r[6] & ~(AOT_N | AOT_Z | AOT_S | AOT_C);
	if (((value >> 16) & 1u) != (((r0 ^ r1) >> 15) & 1u))
		sr |= AOT_S;
	if (value & 0x8000u)
		sr |= AOT_N;
	if ((uint16_t)value == 0)
		sr |= AOT_Z;
	if (value & 0x10000u)
		sr |= AOT_C;
	c->r[6] = sr;
}

// unsp_device::do_basic_alu_ops(), as a value-returning helper.  Returns
// AOT_NO_WRITE when the interpreter would not write the destination register
// (compare / test / store); the caller emits the store itself.
// Sentinel returned by aot_op() for the ops that only touch flags.  It has to
// live outside the range a real result can occupy: Subtract/AddC legitimately
// produce 0x10000 (r0 == r1) and that aliased the old 0x10000 value, silently
// dropping the write-back of e.g. "sub r5, 1" once r5 reached 1.
#define AOT_NO_WRITE 0x80000000u

static inline uint32_t aot_op(AotCtx *c, unsigned op0, uint16_t r0, uint16_t r1, bool fl)
{
	uint32_t v;
	switch (op0)
	{
	case 0x0: // Add
		v = (uint32_t)r0 + r1;
		if (fl) aot_nzsc(c, v, r0, r1);
		return v;
	case 0x1: // Add w/ carry
		v = (uint32_t)r0 + r1 + ((c->r[6] & AOT_C) ? 1u : 0u);
		if (fl) aot_nzsc(c, v, r0, r1);
		return v;
	case 0x2: // Subtract
		v = (uint32_t)r0 + (uint16_t)~r1 + 1u;
		if (fl) aot_nzsc(c, v, r0, (uint16_t)~r1);
		return v;
	case 0x3: // Subtract w/ carry
		v = (uint32_t)r0 + (uint16_t)~r1 + ((c->r[6] & AOT_C) ? 1u : 0u);
		if (fl) aot_nzsc(c, v, r0, (uint16_t)~r1);
		return v;
	case 0x4: // Compare
		v = (uint32_t)r0 + (uint16_t)~r1 + 1u;
		if (fl) aot_nzsc(c, v, r0, (uint16_t)~r1);
		return AOT_NO_WRITE;
	case 0x6: // Negate
		v = (uint32_t)(uint16_t)(0u - (uint32_t)r1);
		if (fl) aot_nz(c, v);
		return v;
	case 0x8: // XOR
		v = (uint32_t)r0 ^ r1;
		if (fl) aot_nz(c, v);
		return v;
	case 0x9: // Load
		v = r1;
		if (fl) aot_nz(c, v);
		return v;
	case 0xa: // OR
		v = (uint32_t)r0 | r1;
		if (fl) aot_nz(c, v);
		return v;
	case 0xb: // AND
		v = (uint32_t)r0 & r1;
		if (fl) aot_nz(c, v);
		return v;
	case 0xc: // Test
		v = (uint32_t)r0 & r1;
		if (fl) aot_nz(c, v);
		return AOT_NO_WRITE;
	default: // illegal ALU type: the interpreter logs and does nothing
		return AOT_NO_WRITE;
	}
}

// push(): store then post-decrement, i.e. SP points at the last pushed word.
static inline void aot_push(AotCtx *c, unsigned sp, uint16_t value)
{
	aot_wr(c, (uint16_t)c->r[sp], value);
	c->r[sp] = (uint16_t)(c->r[sp] - 1u);
}

// pop(): pre-increment then load.
static inline uint16_t aot_pop(AotCtx *c, unsigned sp)
{
	c->r[sp] = (uint16_t)(c->r[sp] + 1u);
	return aot_rd(c, (uint16_t)c->r[sp]);
}

// Instruction-entry hook.  AOT_I is for the first instruction of a block: the
// dispatcher already counted it in the block histogram, so only the trace hook
// fires.  AOT_IH is for the rest.
#define AOT_I(c, pc) \
	do { if ((c)->insn_hook) (c)->insn_hook((c)->insn_opaque, (pc)); } while (0)
#define AOT_IH(c, pc) \
	do { \
		if ((c)->insn_hook) (c)->insn_hook((c)->insn_opaque, (pc)); \
		if ((c)->blk_hist) (c)->blk_hist[(pc) & 0x3ffffu]++; \
	} while (0)
// Charge the instruction's cycles *before* the hook runs, exactly like the
// interpreter, which subtracts from m_icount inside the instruction and only
// then reports the charge.  Blocks therefore leave icount at the same value the
// interpreter would have after the same instruction, and their exit tests see
// the same budget.
#define AOT_CYC(c, pc, n) \
	do { \
		(c)->icount -= (n); \
		if ((c)->cycle_hook) (c)->cycle_hook((c)->cycle_opaque, (pc), (n)); \
	} while (0)

// On the device there is no tracer, no block histogram and no cycle profiler,
// so the hook tests in every emitted instruction are pure overhead -- and they
// are what makes a block 950 bytes instead of 600, which is the difference
// between 60 and 95 blocks fitting in IRAM.  AOT_NO_HOOKS compiles them out.
#ifdef AOT_NO_HOOKS
#undef AOT_I
#undef AOT_IH
#undef AOT_CYC
#define AOT_I(c, pc) ((void)0)
#define AOT_IH(c, pc) ((void)0)
#define AOT_CYC(c, pc, n) ((c)->icount -= (n))
#endif

#ifdef AOT_CONST_TABLES
// Device build: the block tables live in flash as compile-time constants, so the
// page index costs no RAM.  AotPage would need a 16,384-entry pointer array
// (64 KiB) plus 1.8 KiB of function/count/cycle tables per page in .bss, which
// does not fit next to the framebuffer on the C3.  Binary search over the 60-80
// pages that actually carry blocks replaces the direct index; it runs once per
// block entry, so the ~7 compares are noise next to the block body.
//
// fn/cyc/cnt live in one 8-byte struct, not three parallel arrays: with three
// arrays every dispatch read three independent flash lines, and on the C3 that
// is the whole cost of a block (measured ~880 cycles per dispatch, against 78
// cycles in the simulator, which models neither flash latency nor the icache).
// One struct means one line, and a 32-byte line covers four neighbouring slots.
typedef struct
{
	AotFn fn;
	uint16_t cyc;
	uint8_t cnt;
	uint8_t pad;
} AotEnt;

typedef struct AotPageDesc
{
	uint16_t page;
	const AotEnt *ent;
} AotPageDesc;

extern const AotPageDesc g_aot_desc[];
extern const uint32_t g_aot_desc_n;
#else
extern AotPage *g_aot_page[0x4000];
void aot_init(void);
#endif
extern const uint32_t g_aot_block_count;

// Diagnostic: dump the hottest fallback and miss PCs (GPCE4_AOTSTAT=<path>).
#ifndef ESP_PLATFORM
void aot_dump_pc_hist(const char *path);
#endif

#ifdef AOT_CONST_TABLES
// One-entry-per-slot page cache.  Without it every dispatch does a seven-step
// binary search through a flash-resident descriptor array, and on the C3 that
// flash traffic costs more than the block it is looking up: measured 17 fps
// against the interpreter's 59 fps on the busiest scene.  The keys live in
// DRAM (a 3-cycle load).  128 slots, not 64: the device build carries 71 pages,
// so 64 slots guarantees a handful of permanent index collisions and every hit
// on those pages pays the full binary search.  128 slots = 1 KB of DRAM.
// Tagged with page + 1 so the zero-filled state is a permanent miss.
inline uint32_t g_aot_pg_tag[128];
inline const AotPageDesc *g_aot_pg_ref[128];

// Diagnostic only: filled by a page-cache experiment that did not pay off.
// Measured 7,600 page switches per second (36% of all dispatches crossed a page
// boundary), so the block set is spread over all 71 pages and caching whole
// 2 KB pages is a net loss.  Kept at zero so the log format stays stable.
inline uint32_t g_aot_pg_switch;

#endif

static inline AotFn aot_lookup(uint32_t lpc, uint8_t *cnt = nullptr, uint16_t *cyc = nullptr)
{
#ifdef AOT_CONST_TABLES
	const uint32_t page = (lpc >> 8) & 0x3fffu;
	const unsigned pslot = page & 127u;
	const AotPageDesc *d = g_aot_pg_ref[pslot];
	if (g_aot_pg_tag[pslot] != page + 1u)
	{
		uint32_t lo = 0, hi = g_aot_desc_n;
		d = nullptr;
		while (lo < hi)
		{
			const uint32_t mid = (lo + hi) >> 1;
			const AotPageDesc &cand = g_aot_desc[mid];
			if (cand.page == page) { d = &cand; break; }
			if (cand.page < page)
				lo = mid + 1;
			else
				hi = mid;
		}
		g_aot_pg_tag[pslot] = page + 1u;
		g_aot_pg_ref[pslot] = d;
	}
	if (!d)
		return nullptr;
	const AotEnt *const e = &d->ent[lpc & 0xffu];
	if (cnt)
		*cnt = e->cnt;
	if (cyc)
		*cyc = e->cyc;
	return e->fn;
#else
	AotPage *const p = g_aot_page[(lpc >> 8) & 0x3fffu];
	if (!p)
		return nullptr;
	const unsigned slot = lpc & 0xffu;
	if (cnt)
		*cnt = p->cnt[slot];
	if (cyc)
		*cyc = p->cyc[slot];
	return p->fn[slot];
#endif
}

#endif // EMU_AOT_H
